use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr1 = input.as_array().unwrap();
    let arr2 = input.as_array().unwrap();
    let mut result = Vec::new();

    let min_len = arr1.len().min(arr2.len());
    for i in 0..min_len {
        let a = arr1[i].as_i64().unwrap();
        let b = arr2[i].as_i64().unwrap();
        if a.is_none() || b.is_none() {
            result.push(null);
        } else {
            result.push(Some(a.unwrap()));
            result.push(Some(b.unwrap()));
        }
    }

    Value::Array(result)
}
